import { getLanguage } from './i18n.js';
import { esc, specList, tagLine, roomTitle, linkButton, insideButton, label } from './exhibit-frame.js';
const c=(zh,en)=>getLanguage()==='en'?en:zh;
export const lensRepo='https://github.com/ChefDavid0815/projectlens';
const release=`${lensRepo}/releases/tag/v0.1.0`;

// The optical object: post, Now and the Gallery share it; projectlens-motion.js mounts the 3D lens into it.
export function lensObject(compact=false) {
  return `<div class="lens-optics${compact?' lens-optics--compact':''}" data-lens-object aria-hidden="true"><div class="lens-optics-grid"></div><div class="lens-fallback"><i></i><i></i><i></i><b>⌘</b></div><span class="lens-coordinate">X / 024<br>Y / 091</span><span class="lens-optics-caption">OPTICAL STUDY — 005</span><span class="lens-cross lens-cross--a">+</span><span class="lens-cross lens-cross--b">+</span></div>`;
}
export function lensPostArt() {
  return `<div class="post-art post-art--lens" aria-hidden="true"><div class="lens-art-meta"><span>FIELD NOTES / 008</span><span>V0.1.0</span></div><div class="lens-art-word">LOOK<br><i>CLOSER.</i></div>${lensObject(true)}<span class="lens-art-foot">A LITTLE CLARITY IN THE CODE.</span></div>`;
}
export const lensNowArt=()=>`<div class="milestone-art lens-now-art" aria-hidden="true"><div class="lens-art-meta"><span>PROJECT / 05</span><span>LOCAL FIRST</span></div><strong>LOOK<br><i>CLOSER.</i></strong>${lensObject(true)}<span class="lens-art-foot">PROJECTLENS / V0.1.0</span></div>`;
const actionLinks=()=>`<div class="xr-actions">${linkButton({href:release,text:c('下载 Windows 版','Get it for Windows'),iconName:'arrow-down',primary:true})}${linkButton({href:lensRepo,text:'GitHub'})}${linkButton({href:'./post.html?article=projectlens',text:c('制作手记','Build notes'),external:false})}</div>`;
const modes=[
  ['structure','01','结构','Structure','在文件之间，发现轮廓。','Find the shape between the files.','语言、入口候选、依赖清单与目录体量，先认识项目本身。','Languages, entry candidates, manifests and directory sizes: first, understand the project.','src/ → config/ → docs/'],
  ['signals','02','线索','Signals','每一个提醒，都有来处。','Every finding has a place to begin.','检索规则、文件或描述；按严重程度筛选，展开证据与修改建议。','Search rules, files or descriptions. Filter by severity and follow the evidence and suggestions.','file:line → evidence → next step'],
  ['report','03','带走','Report','把下一步，写清楚。','Take a clearer next step.','导出 Markdown 或 JSON，把本地检查结果带进下一次整理。','Export Markdown or JSON and bring the local findings into your next round of work.','local scan → report.md / report.json']
];
const shot=()=>c('./assets/projects/projectlens/workspace.jpg','./assets/projects/projectlens/workspace-en.jpg');
const shotAlt=()=>c('ProjectLens 原始界面，尚未选择文件夹','Actual ProjectLens interface before a folder is selected');
const shotCaption=()=>c('真实界面 · 浏览器渲染的桌面前端。目录扫描需要 Windows 桌面版。','Actual interface · Browser rendering of the desktop frontend. Directory scanning requires the Windows app.');
const tree='<div class="lnx-tree" aria-hidden="true"><div><b></b>project/</div><div>├─ src/<span>TS</span></div><div>├─ package.json<span>{ }</span></div><div>└─ README.md<span>MD</span></div></div>';

export function lensCard(project){return `<article class="exhibit xr xr--lens" id="project-projectlens" data-lens-mode="structure" data-theme="dark"><div class="lnx-rings" aria-hidden="true"></div><div class="xr-inner"><div class="xr-hero"><div class="xr-copy">${roomTitle('Project<wbr>Lens<span class="lnx-caret">_</span>','05')}<p class="lnx-motto">Offline by nature. Curious by design.</p><p class="xr-sub">${c('把线索，放大。','Bring the signals into focus.')}</p><p class="xr-lede">${c('一个安静的本地工作台。读懂代码、配置与文档的轮廓，再看清值得认真处理的细节。','A quiet local workspace. Read the shape of code, configuration and documentation, then look closer at the details that matter.')}</p>${specList([[label.exhibit(),'No. 05'],[label.category(),esc(project.category)],[label.version(),'<span class="xr-data">0.1.0</span> / MVP'],[label.platform(),'Windows x64'],[label.stack(),tagLine(project.tags)]])}${actionLinks()}<div class="xr-actions xr-actions--inside">${insideButton('projectlens',c('走进项目透镜','Inside ProjectLens'))}</div></div><div class="xr-stage lnx-stage"><figure class="lnx-plate"><img src="${shot()}" width="1699" height="982" alt="${shotAlt()}" loading="lazy" decoding="async"><figcaption>${shotCaption()}</figcaption></figure><div class="lnx-lens">${lensObject()}</div><div class="lnx-label" aria-hidden="true"><b>ProjectLens</b><small>READ-ONLY / LOCAL / EXPLAINABLE</small></div><p class="lnx-edge" aria-hidden="true"><span>The local intelligence collection</span><span>Code as a landscape</span></p></div></div><section class="lnx-bench" aria-label="${c('探索三项功能','Explore three capabilities')}"><div class="lnx-modes" role="group" aria-label="${c('功能视角','Feature perspective')}">${modes.map(([id,num,zh,en],i)=>`<button type="button" data-lens-mode-button="${id}" aria-pressed="${i===0}"><span class="xr-data">${num}</span>${c(zh,en)}</button>`).join('')}</div><div class="lnx-panels">${modes.map(([id,,, ,zh,en,desc,descEn,path],i)=>`<div class="lnx-panel" data-lens-panel="${id}"${i?' hidden':''}><div><p class="lnx-path">${path}</p><h4>${c(zh,en)}</h4><p>${c(desc,descEn)}</p></div>${tree}</div>`).join('')}</div><p class="lnx-note">${c('功能导览 · 此展柜不会读取你的文件','Feature tour · This exhibit does not read your files')}</p></section><ul class="lnx-specs"><li><b>LOCAL</b><span>${c('项目内容留在本机','Project content stays local')}</span></li><li><b>5 × 5</b><span>${c('五类规则 · 五级提示','Five categories · Five severity levels')}</span></li><li><b>MD / JSON</b><span>${c('结果清楚，也带得走','Readable. Portable.')}</span></li></ul><footer class="xr-foot"><span>Windows x64 / MVP</span><span>${c('静态启发式检查 · 中英双语','Static heuristic checks · Chinese / English')}</span><span>CHEFZC © 2026</span></footer></div></article>`;}

export function lensDetail(project){const tags=project?.tags||['Electron','React','TypeScript'];return `<div class="xd xd--lens"><header class="xd-head">${roomTitle('ProjectLens<span class="lnx-caret">_</span>','05',{tag:'h2',id:'dialog-title'})}<p class="xr-sub">${c('先看清项目，再决定下一步。','Understand the project. Then choose the next step.')}</p>${specList([[label.category(),'Local project intelligence'],[label.version(),'<span class="xr-data">0.1.0</span>'],[label.platform(),'Windows x64'],[label.stack(),tagLine(tags)]])}</header><figure class="xd-shot lnx-capture"><img src="${shot()}" width="1699" height="982" alt="${shotAlt()}"><figcaption>${shotCaption()}</figcaption></figure><div class="xd-copy"><section><span class="xd-step">01 / Follow the signal</span><div><h3>${c('找到值得留意的地方','Follow what deserves attention')}</h3><p>${c('扫描代码、配置、依赖清单和文档。查看疑似凭据、维护信号、缺失的工程文件和重复代码；通过文件路径、行号、脱敏证据与建议，理解每一项提示。','Scan code, configuration, manifests and documentation. Explore possible credentials, maintenance signals, missing project foundations and duplicate code, with file paths, line numbers, redacted evidence and suggestions.')}</p></div></section><section><span class="xd-step">02 / Clear by design</span><div><h3>${c('用熟悉的语言，看清楚','Clarity, in your language')}</h3><p>${c('右上角可选中文、English 或跟随系统，偏好留在本机；界面、提示和导出随语言切换。这是 v0.1.0 静态规则工具，不调用远程 AI 或漏洞数据库。提示可能有误报或遗漏，不能替代编译、测试与安全审计；Windows 便携包未签名。','Choose Chinese, English or Auto in the top-right selector. Your preference stays local; the interface, messages and exports follow it. This v0.1.0 static-rule tool does not call remote AI or a vulnerability database. Findings can miss issues or produce false positives; they do not replace compilation, testing or security review. The Windows portable build is unsigned.')}</p></div></section></div><div class="xd-actions">${actionLinks()}</div></div>`;}

export function setLensMode(button){
 const host=button.closest('.xr--lens');if(!host)return;
 const mode=button.dataset.lensModeButton;host.dataset.lensMode=mode;
 host.querySelectorAll('[data-lens-mode-button]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
 host.querySelectorAll('[data-lens-panel]').forEach(p=>p.hidden=p.dataset.lensPanel!==mode);
 host.dispatchEvent(new CustomEvent('lens-mode',{bubbles:true,detail:mode}));
}
